<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{BadgeCheck,UserRound}from'lucide-vue-next';import{api}from'@/services/api';import{errorMessage}from'@/services/http';import{useAuthStore}from'@/stores/auth';import type{UserIdentity}from'@/types';const auth=useAuthStore();const identity=ref<UserIdentity|null>(null);const form=reactive({realName:'',idType:'ID_CARD',idNo:''});const message=ref('');onMounted(async()=>{try{identity.value=await api.identity()}catch{identity.value=null}});async function bind(){try{identity.value=await api.bindIdentity(form);message.value='实名认证成功'}catch(e){message.value=errorMessage(e)}}</script>
<template><section class="page container narrow"><header class="page-head"><div><p class="eyebrow">PROFILE</p><h1>个人中心</h1></div></header><article class="profile-card"><UserRound/><div><h2>{{auth.user?.username}}</h2><p>{{auth.user?.phone||'未绑定手机号'}}</p></div><span>普通用户</span></article><article class="identity-card"><header><div><BadgeCheck/><div><h2>实名认证</h2><p>实名认证后可查询本人作为乘车人的车票</p></div></div><span :class="identity?'verified':''">{{identity?'已认证':'未认证'}}</span></header><div v-if="identity" class="identity-info"><p><span>真实姓名</span>{{identity.realName}}</p><p><span>证件类型</span>{{identity.idType}}</p><p><span>证件号码</span>{{identity.idNo}}</p><p><span>认证时间</span>{{identity.verifiedAt?.replace('T',' ').slice(0,16)}}</p></div><form v-else class="stack-form" @submit.prevent="bind"><label>真实姓名<input v-model.trim="form.realName" required></label><label>证件类型<select v-model="form.idType"><option value="ID_CARD">居民身份证</option></select></label><label>证件号码<input v-model.trim="form.idNo" required></label><p v-if="message" class="notice">{{message}}</p><button class="btn primary">提交认证</button></form></article></section></template>
